// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    Log lg;

    function setUp() public {
        address logAddr = address(new Log());
        lg = Log(logAddr);
        c = new X_WALLET(address(new Log()));
        // re-deploy once so c uses the same Log we can inspect
        c = new X_WALLET(logAddr);
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 10 ether);

        // number of history entries before
        uint256 beforeLen = histLen();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // exactly one new entry, matching this deposit
        assertTrue(histLen() == beforeLen + 1);
    }

    function histLen() internal view returns (uint256 n) {
        // History entries can be read via the public getter; find count by probing
        n = 0;
        while (true) {
            try this.probe(address(lg), n) returns (bool ok) {
                if (!ok) return n;
                n++;
            } catch {
                return n;
            }
        }
    }

    function probe(address l, uint256 i) external view returns (bool) {
        try Log(l).History(i) returns (address, string memory, uint256, uint256) {
            return true;
        } catch {
            return false;
        }
    }
}
